<template>
    <div>
      <div v-html="mapCode"></div>
    </div>
  </template>
  
  <script>
  export default {
    data() {
      return {
        mapCode: "",
      };
    },
    mounted() {
      // Replace the map code with your actual map code
      const encodedMapCode = "";
        // Use atob to decode the map code
        const decodedMapCode = atob(encodedMapCode);
        // Set the map code to the component data
        this.mapCode = decodedMapCode;
      },
  };
  </script>
  
